-- Venue Live Guest "Birthday Little Scientist". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara littlescientist), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'littlescientist', 'Birthday Little Scientist (laboratorium sains)', 'littlescientist', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 127, 'center 38%',
  $t${"name":"Little Scientist","orn":"diamond","ui":{"ivory":"#F7F3FF","white":"#FFFFFF","soft":"#E6DBFF","soft2":"#B9A3F0","accent":"#7A4FD6","deep":"#3C2380","ink":"#2A1A5E","mute":"#7A6BA8","line":"#D9CCF5","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FBF9FF","ink":"#2A1A5E","accent":"#7A4FD6","gold":"#F2B705","leaf":"#E6DBFF","hbg":"rgba(247,243,255,.94)","hline":"#B9A3F0","motif":"diamond"},"hud":{"bg":"rgba(60,35,128,.86)","acc":"#FFD84D","on":"#2A1A5E"},"scr":{"wine":"#3C2380","veil":"247,243,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'littlescientist');
